const data = $json.body ?? $json;

const requiredFields = [
  'player',
  'score',
  'correctAnswers',
  'totalQuestions',
  'level'
];

const missingFields = requiredFields.filter(
  (field) => data[field] === undefined || data[field] === null || data[field] === ''
);

if (missingFields.length > 0) {
  throw new Error(`Faltan datos requeridos: ${missingFields.join(', ')}`);
}

return [
  {
    json: {
      player: String(data.player),
      score: Number(data.score),
      correctAnswers: Number(data.correctAnswers),
      totalQuestions: Number(data.totalQuestions),
      level: String(data.level),
      scoreId: data.scoreId ?? null,
      receivedAt: new Date().toISOString()
    }
  }
];

const data = $json;

const percentage = data.totalQuestions > 0
  ? Math.round((data.correctAnswers / data.totalQuestions) * 100)
  : 0;

let performance = 'Necesita mejorar';

if (percentage >= 90) {
  performance = 'Excelente';
} else if (percentage >= 70) {
  performance = 'Buen resultado';
} else if (percentage >= 50) {
  performance = 'Resultado aceptable';
}

return [
  {
    json: {
      ...data,
      percentage,
      performance
    }
  }
];

const data = $json;

return [
  {
    json: {
      success: true,
      player: data.player,
      score: data.score,
      correctAnswers: data.correctAnswers,
      totalQuestions: data.totalQuestions,
